"use client"

import * as React from "react"
import { AnimateIcon } from "@/components/animate-ui/icons/icon"
import { ChevronRight } from "@/components/animate-ui/icons/chevron-right"
import { motion, useMotionValue, useSpring, useTransform } from "motion/react"
import { cn } from "@/lib/utils"
import { LiquidSearch } from "@/components/ui/liquid-search"

type GlassSidebarItem = {
  id: string
  label: string
  icon?: React.ReactNode
  badge?: string
  href?: string
  /** Additional terms matched by the local search. */
  keywords?: string
}
type GlassSidebarHeading = { heading: string }
type GlassSidebarProps = Omit<React.ComponentProps<"aside">, "children" | "defaultValue" | "onChange"> & {
  items: (GlassSidebarItem | GlassSidebarHeading)[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  /** Replaces the brand row above search. */
  header?: React.ReactNode
  /** Account details or other content anchored below navigation. */
  footer?: React.ReactNode
  /** Shows a local filter for the navigation rows. */
  searchable?: boolean
  searchPlaceholder?: string
}

const reducedMotionQuery = "(prefers-reduced-motion: reduce)"
function subscribeReducedMotion(onChange: () => void) {
  const media = window.matchMedia(reducedMotionQuery)
  media.addEventListener("change", onChange)
  return () => media.removeEventListener("change", onChange)
}
const readReducedMotion = () => window.matchMedia(reducedMotionQuery).matches
const serverReducedMotion = () => true

function GlassSidebar({ items, value, defaultValue, onValueChange, header, footer, searchable = true, searchPlaceholder = "Find a page", className, "aria-label": label = "Sidebar", ...props }: GlassSidebarProps) {
  const [query, setQuery] = React.useState("")
  const [internal, setInternal] = React.useState(defaultValue ?? items.find(item => "id" in item)?.id)
  const [hovered, setHovered] = React.useState<string | null>(null)
  const [focused, setFocused] = React.useState<string | null>(null)
  const uid = React.useId()
  const reduceMotion = React.useSyncExternalStore(subscribeReducedMotion, readReducedMotion, serverReducedMotion)
  const active = value ?? internal
  const highlighted = hovered ?? focused ?? active
  const nav = React.useRef<HTMLElement>(null)
  const [track, setTrack] = React.useState<{ top: number; bottom: number; width: number; rows: Record<string, number>; heights: Record<string, number> } | null>(null)
  const lineStart = useMotionValue(0)
  const lineEnd = useMotionValue(0)
  const lineWidth = useMotionValue(240)
  const rowHeight = useMotionValue(36)
  const lineY = useSpring(0, { stiffness: 400, damping: 40, mass: 0.8 })
  const ready = React.useRef(false)
  const target = track?.rows[highlighted ?? ""]
  // One continuous seam opens out around the current row, then rejoins below it.
  // Keeping the same path commands lets direction changes stay interruptible.
  const box = (y: number, width: number, height: number) => {
    const top = y - height / 2
    const bottom = y + height / 2
    // every corner shares one radius, and the row stops short of the scrollbar
    const r = Math.min(12, height / 2)
    const right = Math.max(32, width - 6)
    return { top, bottom, r, right, edge: `H ${right - r} Q ${right} ${top} ${right} ${top + r} V ${bottom - r} Q ${right} ${bottom} ${right - r} ${bottom} H ${9 + r}` }
  }
  const contour = useTransform([lineY, lineWidth, rowHeight], ([y, width, height]: number[]) => {
    const { top, bottom, r, edge } = box(y, width, height)
    return `M 9 ${top - r} Q 9 ${top} ${9 + r} ${top} ${edge} Q 9 ${bottom} 9 ${bottom + r}`
  })
  const seam = useTransform([lineStart, lineEnd, lineY, lineWidth, rowHeight], ([start, end, y, width, height]: number[]) => {
    const { top, bottom, r, edge } = box(y, width, height)
    return `M 9 ${start} V ${top - r} Q 9 ${top} ${9 + r} ${top} ${edge} Q 9 ${bottom} 9 ${bottom + r} V ${end}`
  })
  // the fill follows the outline's rounded left corners instead of poking past them
  const rowFill = useTransform([lineY, lineWidth, rowHeight], ([y, width, height]: number[]) => {
    const { top, bottom, r, edge } = box(y, width, height)
    return `M 9 ${top + r} Q 9 ${top} ${9 + r} ${top} ${edge} Q 9 ${bottom} 9 ${bottom - r} Z`
  })

  function choose(id: string) {
    if (value === undefined) setInternal(id)
    onValueChange?.(id)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLElement>) {
    const rows = [...(nav.current?.querySelectorAll<HTMLElement>("[data-sidebar-item]") ?? [])]
    const index = rows.indexOf(event.target as HTMLElement)
    if (index < 0) return
    const target = event.key === "ArrowDown" ? Math.min(index + 1, rows.length - 1)
      : event.key === "ArrowUp" ? Math.max(index - 1, 0)
      : event.key === "Home" ? 0 : event.key === "End" ? rows.length - 1 : null
    if (target === null) return
    event.preventDefault()
    setHovered(null)
    rows[target]?.focus()
  }
  const visible = React.useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return items
    const result: (GlassSidebarItem | GlassSidebarHeading)[] = []
    let heading: GlassSidebarHeading | undefined
    for (const item of items) {
      if ("heading" in item) heading = item
      else if (`${item.label} ${item.keywords ?? ""}`.toLowerCase().includes(q)) {
        if (heading) { result.push(heading); heading = undefined }
        result.push(item)
      }
    }
    return result
  }, [items, query])
  // Measure only on layout changes; spring values move the SVG without React renders.
  React.useLayoutEffect(() => {
    const root = nav.current
    if (!root) { ready.current = false; return }
    const measure = () => {
      const bounds = root.getBoundingClientRect()
      const rows: Record<string, number> = {}
      const heights: Record<string, number> = {}
      root.querySelectorAll<HTMLElement>("[data-sidebar-item]").forEach(row => {
        const rect = row.getBoundingClientRect()
        rows[row.dataset.sidebarItem!] = rect.top - bounds.top + rect.height / 2
        heights[row.dataset.sidebarItem!] = rect.height
      })
      const positions = Object.values(rows)
      if (!positions.length) { setTrack(null); return }
      setTrack({ top: 0, bottom: bounds.height, width: bounds.width, rows, heights })
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(root)
    root.querySelectorAll("[data-sidebar-item]").forEach(row => observer.observe(row))
    return () => observer.disconnect()
  }, [visible])

  React.useLayoutEffect(() => {
    if (!track) return
    lineStart.set(track.top)
    lineEnd.set(track.bottom)
    lineWidth.set(track.width)
    rowHeight.set(track.heights[highlighted ?? ""] ?? 36)
    if (target === undefined) return
    if (!ready.current || reduceMotion) lineY.jump(target)
    else lineY.set(target)
    ready.current = true
  }, [highlighted, lineEnd, lineStart, lineWidth, lineY, reduceMotion, rowHeight, target, track])

  return <aside data-slot="glass-sidebar" aria-label={label} className={cn("relative flex min-h-96 w-full max-w-[264px] min-w-0 flex-col overflow-hidden rounded-[24px] border border-foreground/[0.09] bg-card/95 text-foreground antialiased shadow-[inset_0_1px_0_var(--gloss-highlight),0_16px_40px_-24px_var(--gloss-depth)] backdrop-blur-xl", className)} {...props}>
    <div data-slot="sidebar-header" className="shrink-0 px-2 pb-1 pt-3">
      {header ?? <div className="flex items-center gap-3">
        <span className="grid size-8 shrink-0 place-items-center rounded-concentric border border-foreground/[0.08] bg-linear-to-b from-foreground/[0.055] to-foreground/[0.025] shadow-[inset_0_1px_0_var(--gloss-highlight)]"><svg aria-hidden viewBox="0 0 24 24" className="size-5 text-glow"><path d="M5.5 14a6.5 6.5 0 0 1 13 0Z" fill="currentColor" /><path d="M3 17h18M7.5 20h9" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" /></svg></span>
        <div className="min-w-0"><p className="text-sm font-semibold tracking-tight">Afterglow</p><p className="mt-0.5 text-[11px] text-muted-foreground">Workspace</p></div>
        <span className="ml-auto rounded-md border border-foreground/[0.08] px-1.5 py-0.5 text-[10px] tabular-nums text-foreground/40">1.0</span>
      </div>}
      {searchable && <LiquidSearch className="mt-3" aria-label={searchPlaceholder} placeholder={searchPlaceholder} value={query} onValueChange={setQuery} />}

    </div>
    <div data-slot="sidebar-scroll" className="min-h-0 flex-1 overflow-y-auto px-2 pb-2 pt-1 [scrollbar-width:thin]">
      {visible.length ? <nav ref={nav} className="relative py-3" aria-label={`${label} links`} onKeyDown={onKeyDown} onPointerLeave={() => setHovered(null)} onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget)) setFocused(null) }}>
        {track && target !== undefined && <svg aria-hidden data-sidebar-line className="pointer-events-none absolute inset-0 h-full w-full overflow-visible">
          <defs><linearGradient id={`${uid}-line`} x1="0" y1="0" x2="1" y2="0"><stop stopColor="var(--glow)" stopOpacity="0.2" /><stop offset="0.5" stopColor="var(--glow)" stopOpacity="0.5" /><stop offset="1" stopColor="var(--glow)" stopOpacity="0.3" /></linearGradient></defs>
          <motion.path data-sidebar-fill d={rowFill} fill="currentColor" fillOpacity="0.055" />
          <motion.path data-sidebar-seam d={seam} fill="none" stroke="currentColor" strokeOpacity="0.13" strokeWidth="1" strokeLinecap="round" />
          <motion.path data-sidebar-contour d={contour} fill="none" stroke={`url(#${uid}-line)`} strokeWidth="1" strokeLinecap="round" />
        </svg>}
        <ul className="space-y-0.5 pl-5">
          {visible.map((item, index) => {
            if ("heading" in item) return <li key={`heading-${index}`} className={cn("flex items-center gap-3 px-3 pb-1.5 pt-3 text-[11px] font-medium text-foreground/45", index === 0 && "pt-0")}><span>{item.heading}</span><span aria-hidden className="h-px flex-1 bg-foreground/[0.06]" /></li>
            const selected = active === item.id
            const contents = <>
              {/* concentric-ignore: mid-row, not in a corner of the panel */}
              {item.icon && <span aria-hidden className={cn("relative grid size-7 shrink-0 place-items-center rounded-[8px] transition-colors duration-200 [&>svg]:size-[15px] [&>svg]:stroke-[1.65]", selected || highlighted === item.id ? "text-glow" : "text-foreground/50 group-hover:text-foreground/80")}>{item.icon}</span>}
              <span className="relative min-w-0 flex-1 truncate">{item.label}</span>
              {/* concentric-ignore: mid-row, not in a corner of the panel */}
              {item.badge ? <span className={cn("relative min-w-5 shrink-0 rounded-md border border-foreground/[0.07] bg-foreground/[0.025] px-1.5 py-0.5 text-center text-[10px] leading-none tabular-nums transition-colors duration-150", selected ? "text-glow" : "text-foreground/45")}>{item.badge}</span> : <ChevronRight aria-hidden size={13} className={cn("relative shrink-0 transition-[opacity,translate] duration-200 motion-reduce:transition-none", highlighted === item.id ? "translate-x-0 opacity-50" : "-translate-x-1 opacity-0")} />}
            </>
            const common = {
              "data-sidebar-item": item.id,
              "aria-current": selected ? "page" as const : undefined,
              className: cn("group relative flex min-h-9 scroll-my-3 w-full cursor-pointer items-center gap-2.5 rounded-[12px] px-2.5 py-1 text-left text-[13px] outline-none transition-colors duration-150 focus-visible:ring-2 focus-visible:ring-glow/60 motion-reduce:transition-none", selected ? "font-medium text-foreground" : "text-foreground/60 hover:text-foreground focus-visible:text-foreground"),
              onPointerEnter: (event: React.PointerEvent) => { if (event.pointerType !== "touch") setHovered(item.id) },
              onFocus: () => setFocused(item.id),
              onClick: () => choose(item.id),
            }
            return <li key={item.id}><AnimateIcon animateOnHover asChild>{item.href ? <a {...common} href={item.href}>{contents}</a> : <button {...common} type="button">{contents}</button>}</AnimateIcon></li>
          })}
        </ul>
      </nav> : <p role="status" className="px-3 text-xs text-muted-foreground">No matching pages.</p>}
    </div>
    {footer && <div className="shrink-0 border-t border-foreground/[0.06] bg-foreground/[0.01] p-3">{footer}</div>}
  </aside>
}

export { GlassSidebar, type GlassSidebarProps, type GlassSidebarItem, type GlassSidebarHeading }

"use client"

import * as React from "react"
import { AnimateIcon } from "@/components/animate-ui/icons/icon"
import { Search } from "@/components/animate-ui/icons/search"
import { X } from "@/components/animate-ui/icons/x"
import { LiquidGlass } from "@/components/ui/liquid-glass"
import { cn } from "@/lib/utils"

type LiquidSearchProps = Omit<React.ComponentProps<"input">, "type" | "size" | "value" | "defaultValue" | "onChange"> & {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Styles the input text separately from the glass capsule. */
  inputClassName?: string
}

function LiquidSearch({ value, defaultValue = "", onValueChange, placeholder = "Search anything", className, inputClassName, disabled, readOnly, ref, onKeyDown, "aria-label": label, ...props }: LiquidSearchProps) {
  const [internal, setInternal] = React.useState(defaultValue)
  const input = React.useRef<HTMLInputElement>(null)
  React.useImperativeHandle(ref, () => input.current!, [])
  const text = value ?? internal
  function update(next: string) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }
  function clear() {
    update("")
    input.current?.focus()
  }
  return <AnimateIcon animateOnHover asChild><div data-slot="liquid-search" className={cn("group relative flex h-9 w-full min-w-0 items-center gap-2 rounded-[16px] p-1 text-foreground transition-shadow duration-200 focus-within:ring-2 focus-within:ring-glow/25", disabled && "pointer-events-none opacity-50", className)}>
    <LiquidGlass refraction={0} frost={6} tint="color-mix(in oklch, var(--card) 35%, transparent)" className="pointer-events-none absolute inset-0 rounded-[inherit]" />
    <span aria-hidden className="relative grid size-7 shrink-0 place-items-center rounded-concentric bg-linear-to-b from-foreground/[0.065] to-foreground/[0.015] text-foreground/50 shadow-gloss transition-[color,scale] duration-200 group-focus-within:scale-[1.04] group-focus-within:text-glow motion-reduce:transition-none motion-reduce:group-focus-within:scale-100"><Search aria-hidden size={14} strokeWidth={1.7} /></span>
    <input {...props} ref={input} aria-label={label ?? placeholder} type="search" disabled={disabled} readOnly={readOnly} placeholder={placeholder} value={text} onChange={event => update(event.target.value)} onKeyDown={event => {
      onKeyDown?.(event)
      if (!event.defaultPrevented && !event.nativeEvent.isComposing && event.key === "Escape" && text && !readOnly) {
        event.preventDefault()
        clear()
      }
    }} className={cn("relative h-full min-w-0 flex-1 appearance-none bg-transparent text-xs outline-none placeholder:text-foreground/40 [&::-webkit-search-cancel-button]:appearance-none", inputClassName)} />
    <AnimateIcon animateOnHover asChild><button type="button" aria-label="Clear search" disabled={disabled || readOnly || !text} tabIndex={text && !readOnly ? 0 : -1} onClick={clear} className={cn("relative grid size-6 shrink-0 cursor-pointer place-items-center rounded-concentric text-foreground/45 outline-none transition-[opacity,background-color] duration-150 hover:bg-foreground/[0.07] hover:text-foreground focus-visible:ring-2 focus-visible:ring-glow/50", text && !readOnly ? "opacity-100" : "pointer-events-none opacity-0")}><X aria-hidden size={13} /></button></AnimateIcon>
  </div></AnimateIcon>
}

export { LiquidSearch, type LiquidSearchProps }

"use client"

import * as React from "react"
import {
  isMotionValue,
  motion,
  useMotionValue,
  useTransform,
  type MotionValue,
} from "motion/react"

import { ringMask } from "@/lib/afterglow"
import { cn } from "@/lib/utils"

/*
 * Liquid glass: a pane that bends whatever sits behind it, like Apple's
 * Liquid Glass. The rim is a curved lens, so content near the edges is
 * pulled inward, while the flat middle stays clear.
 *
 * Refraction is an SVG displacement map used as a backdrop-filter, which only
 * Chromium supports. Other browsers get a frosted fallback with the same rim.
 */

const SAMPLES = 128
const INDEX_OF_REFRACTION = 1.5

// convex squircle: flat in the middle, rounding off toward the rim
const surface = (x: number) => Math.pow(1 - Math.pow(1 - x, 4), 0.25)

// how far a straight-down ray is bent sideways at each point across the rim
function rimProfile(bezel: number) {
  const profile = new Float32Array(SAMPLES)
  for (let i = 0; i < SAMPLES; i++) {
    const x = i / (SAMPLES - 1)
    const a = Math.max(x - 0.001, 0)
    const b = Math.min(x + 0.001, 1)
    const slope = (surface(b) - surface(a)) / (b - a)
    const incident = Math.atan(slope)
    const refracted = Math.asin(Math.sin(incident) / INDEX_OF_REFRACTION)
    const thickness = bezel * (0.25 + surface(x))
    profile[i] = thickness * Math.tan(incident - refracted)
  }
  return profile
}

type DisplacementMap = { url: string; scale: number }
const maps = new Map<string, DisplacementMap>()

function displacementMap(
  width: number,
  height: number,
  radius: number,
  bezel: number,
  magnify: number
): DisplacementMap {
  const key = [width, height, radius, bezel, magnify].join(":")
  const cached = maps.get(key)
  if (cached) return cached

  const profile = rimProfile(bezel)
  const dx = new Float32Array(width * height)
  const dy = new Float32Array(width * height)
  let max = 0

  for (let j = 0; j < height; j++) {
    for (let i = 0; i < width; i++) {
      // signed distance to a rounded rectangle, and the outward normal
      const px = i + 0.5 - width / 2
      const py = j + 0.5 - height / 2
      const qx = Math.abs(px) - width / 2 + radius
      const qy = Math.abs(py) - height / 2 + radius
      const inside =
        -(Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) +
          Math.min(Math.max(qx, qy), 0) -
          radius)
      let nx = 0
      let ny = 0
      if (qx > 0 && qy > 0) {
        const length = Math.hypot(qx, qy) || 1
        nx = (qx / length) * Math.sign(px)
        ny = (qy / length) * Math.sign(py)
      } else if (qx > qy) nx = Math.sign(px)
      else ny = Math.sign(py)

      let x = -px * magnify
      let y = -py * magnify
      if (inside >= 0 && inside < bezel) {
        // sample inward, so the rim shows what's just inside the edge
        const shift = profile[Math.round((inside / bezel) * (SAMPLES - 1))]
        x -= nx * shift
        y -= ny * shift
      }
      const k = j * width + i
      dx[k] = x
      dy[k] = y
      max = Math.max(max, Math.abs(x), Math.abs(y))
    }
  }

  const canvas = document.createElement("canvas")
  canvas.width = width
  canvas.height = height
  const context = canvas.getContext("2d")
  if (!context) return { url: "", scale: 0 }
  const image = context.createImageData(width, height)
  for (let k = 0; k < width * height; k++) {
    // 128 is "no shift"; red moves along x, green along y
    image.data[k * 4] = 128 + (dx[k] / (max || 1)) * 127
    image.data[k * 4 + 1] = 128 + (dy[k] / (max || 1)) * 127
    image.data[k * 4 + 2] = 128
    image.data[k * 4 + 3] = 255
  }
  context.putImageData(image, 0, 0)

  const map = { url: canvas.toDataURL(), scale: max * 2 }
  if (maps.size > 48) maps.delete(maps.keys().next().value!)
  maps.set(key, map)
  return map
}

// only Chromium can use an SVG filter as a backdrop-filter
function canRefract() {
  const nav = navigator as Navigator & {
    userAgentData?: { brands: { brand: string }[] }
  }
  if (nav.userAgentData) {
    return nav.userAgentData.brands.some((b) => b.brand === "Chromium")
  }
  return /Chrome\/\d+/.test(nav.userAgent) && !/Firefox|FxiOS/.test(nav.userAgent)
}

const noopSubscribe = () => () => {}

function useCanRefract() {
  return React.useSyncExternalStore(noopSubscribe, canRefract, () => false)
}

type LiquidGlassProps = React.ComponentProps<"div"> & {
  /** width of the curved rim in px, defaults to the corner radius (max 24) */
  bezel?: number
  /** 0 is flat glass, 1 is the full lens; pass a motion value to animate it */
  refraction?: number | MotionValue<number>
  /** zooms the middle like a magnifier, 0 to 0.3 */
  magnify?: number
  /** blur behind the glass in px */
  frost?: number
  /** a color mixed over the glass, e.g. for a tinted primary button */
  tint?: string
  /**
   * fades the whole pane in and out. Never fade a parent of liquid glass
   * instead: an ancestor with opacity cuts the glass off from what's behind it.
   */
  presence?: number | MotionValue<number>
}

function LiquidGlass({
  bezel,
  refraction = 1,
  magnify = 0,
  frost = 1,
  tint,
  presence = 1,
  className,
  children,
  ...props
}: LiquidGlassProps) {
  const ref = React.useRef<HTMLDivElement>(null)
  const displaceRef = React.useRef<SVGFEDisplacementMapElement>(null)
  const id = `liquid-${React.useId().replace(/[^a-zA-Z0-9_-]/g, "")}`
  const canRefractHere = useCanRefract()
  // A fixed zero opts out of SVG backdrop sampling entirely. Native frosting avoids
  // clipped-backdrop seams when flat panes overlap and change stacking order.
  // Motion values still keep the map ready so they can animate away from zero.
  const refract = canRefractHere && (typeof refraction !== "number" || refraction > 0)
  const [shape, setShape] = React.useState<{ w: number; h: number; r: number }>()
  // the scale last written to the filter, so a no-op resize can put it back
  const applied = React.useRef(0)

  React.useEffect(() => {
    const node = ref.current
    if (!node || !refract) return
    const measure = () => {
      const w = Math.round(node.offsetWidth)
      const h = Math.round(node.offsetHeight)
      const raw = getComputedStyle(node).borderTopLeftRadius
      const value = parseFloat(raw) || 0
      const r = Math.round(
        Math.min(raw.endsWith("%") ? (value / 100) * Math.min(w, h) : value, w / 2, h / 2)
      )
      setShape((prev) => {
        if (prev?.w === w && prev.h === h && prev.r === r) {
          displaceRef.current?.setAttribute("scale", String(applied.current))
          return prev
        }
        return { w, h, r }
      })
    }
    // measure right away, then wait for resizing to settle before rebuilding the map
    let first = true
    let frame = 0
    let timer = 0
    const observer = new ResizeObserver(() => {
      if (first) {
        first = false
        measure()
        return
      }
      // until the new map is ready, the old one would bend the wrong pixels
      displaceRef.current?.setAttribute("scale", "0")
      window.clearTimeout(timer)
      timer = window.setTimeout(() => {
        frame = requestAnimationFrame(measure)
      }, 100)
    })
    observer.observe(node)
    return () => {
      observer.disconnect()
      window.clearTimeout(timer)
      cancelAnimationFrame(frame)
    }
  }, [refract])

  const map = React.useMemo(() => {
    if (!refract || !shape || shape.w < 2 || shape.h < 2) return undefined
    const rim = Math.max(1, Math.min(bezel ?? Math.min(shape.r, 24), shape.w / 2, shape.h / 2))
    return displacementMap(shape.w, shape.h, shape.r, Math.round(rim), magnify)
  }, [bezel, magnify, refract, shape])

  // animate refraction by scaling the filter, without rebuilding the map
  React.useEffect(() => {
    if (!map) return
    const apply = (v: number) => {
      applied.current = map.scale * v
      displaceRef.current?.setAttribute("scale", String(applied.current))
    }
    if (typeof refraction === "number") {
      apply(refraction)
      return
    }
    apply(refraction.get())
    return refraction.on("change", apply)
  }, [map, refraction])

  const ownPresence = useMotionValue(isMotionValue(presence) ? 1 : presence)
  const visible = isMotionValue(presence) ? presence : ownPresence
  React.useEffect(() => {
    if (!isMotionValue(presence)) ownPresence.set(presence)
  }, [ownPresence, presence])
  const rimOpacity = useTransform(visible, (v) => v * 0.95)

  const strength = isMotionValue(refraction) ? refraction.get() : refraction
  const backdrop = map
    ? `url(#${id})`
    : `blur(${Math.max(frost, 10)}px) saturate(1.6)`

  return (
    <div
      ref={ref}
      data-slot="liquid-glass"
      // no isolation here: an isolated parent cuts the glass off from the scene
      // behind it in Chrome. Layers stack in source order, and direct children
      // are made relative so they sit on top (wrap an absolute child to keep it).
      className={cn("relative [&>:where(:not([data-glass-layer]))]:relative", className)}
      {...props}
    >
      {map && (
        <svg data-glass-layer aria-hidden width="0" height="0" className="pointer-events-none absolute">
          <filter id={id} colorInterpolationFilters="sRGB">
            <feGaussianBlur in="SourceGraphic" stdDeviation={frost} result="frost" />
            <feImage
              href={map.url}
              x="0"
              y="0"
              width={shape?.w}
              height={shape?.h}
              preserveAspectRatio="none"
              result="map"
            />
            <feDisplacementMap
              ref={displaceRef}
              in="frost"
              in2="map"
              scale={map.scale * strength}
              xChannelSelector="R"
              yChannelSelector="G"
              result="bent"
            />
            {/* glass makes what's behind it a little brighter and more vivid */}
            <feColorMatrix in="bent" type="saturate" values="1.45" result="vivid" />
            <feComponentTransfer in="vivid">
              <feFuncR type="linear" slope="1.05" />
              <feFuncG type="linear" slope="1.05" />
              <feFuncB type="linear" slope="1.05" />
            </feComponentTransfer>
          </filter>
        </svg>
      )}
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[0_10px_30px_-10px_var(--liquid-shadow),0_2px_8px_-2px_var(--liquid-shadow)]"
        style={{ opacity: visible }}
      />
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit]"
        style={{
          backdropFilter: backdrop,
          WebkitBackdropFilter: backdrop,
          opacity: visible,
        }}
      />
      {/* tint, heavier when there's no refraction so text stays legible */}
      <motion.div
        data-glass-layer
        aria-hidden
        className={cn(
          "pointer-events-none absolute inset-0 rounded-[inherit] bg-(--liquid-tint)",
          !map && "bg-(--liquid-fallback)"
        )}
        style={tint ? { background: tint, opacity: visible } : { opacity: visible }}
      />
      {/* volume: light gathers inside the top edge, shade settles along the bottom */}
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[inset_0_1px_16px_-4px_var(--liquid-glow),inset_0_-12px_20px_-14px_var(--liquid-shade)]"
        style={{ opacity: visible }}
      />
      {/* rim light: bright where the light comes from (top left), softer opposite */}
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[inset_0_0_0_0.5px_var(--liquid-edge),inset_1px_1.5px_1px_-1px_var(--liquid-rim),inset_-1px_-1.5px_1px_-1px_color-mix(in_oklch,var(--liquid-rim)_45%,transparent)]"
        style={{ opacity: visible }}
      />
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] p-px"
        style={{
          ...ringMask,
          background:
            "conic-gradient(from 300deg, var(--liquid-rim), transparent 70deg, transparent 110deg, color-mix(in oklch, var(--liquid-rim) 55%, transparent) 180deg, transparent 250deg, transparent 290deg, var(--liquid-rim))",
          opacity: rimOpacity,
        }}
      />
      {children}
    </div>
  )
}

export { LiquidGlass, useCanRefract, type LiquidGlassProps }

import type { CSSProperties } from "react"
import type { TargetAndTransition, Transition } from "motion/react"

// shared spring presets, every component picks from these
export const springs = {
  snappy: { stiffness: 520, damping: 34, mass: 0.6 },
  soft: { stiffness: 260, damping: 26, mass: 0.8 },
  glide: { stiffness: 120, damping: 20, mass: 1 },
} as const

export type SpringName = keyof typeof springs

export function spring(name: SpringName): Transition {
  return { type: "spring", ...springs[name] }
}

// how a glow fades once its source moves away: slow, with a long tail
export const afterglow = {
  linger: 0.9,
  ease: [0.22, 1, 0.36, 1],
} as const satisfies { linger: number; ease: Transition["ease"] }

// paints only the padding ring of an element, used for glowing borders
export const ringMask: CSSProperties = {
  WebkitMask:
    "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  WebkitMaskComposite: "xor",
  mask: "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  maskComposite: "exclude",
}

// small icon gestures, played when a control is pressed or selected
export const iconGestures = {
  pop: { scale: [1, 1.2, 1] },
  ring: { rotate: [0, -18, 14, -9, 4, 0], scale: [1, 1.12, 1] },
  // a gear looks the same after half a turn, so it can rest there and snap back unseen
  turn: { rotate: [0, 180], scale: [1, 1.12, 1] },
  hop: { y: [0, -3, 0], scale: [1, 1.1, 1] },
  nudge: { x: [0, 2.5, 0], scale: [1, 1.1, 1] },
} satisfies Record<string, TargetAndTransition>

export type IconGesture = keyof typeof iconGestures

// leaving a gesture is instant: every gesture already ends at, or looks like, its resting pose
export const iconRest: TargetAndTransition = { scale: 1, rotate: 0, x: 0, y: 0, transition: { duration: 0 } }
